       function FormField({ id, label, type, placeholder, required, helperText }) {
         const describedBy = [helperText ? id + "-helper" : "", id + "-error"].filter(Boolean).join(" ");

         return `
           <div class="form-field" data-invalid="false">
             <label for="${id}">
               ${label}${required ? ' <span class="required-badge" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${id}"
