               autocomplete="${id === "email" ? "email" : id === "phone" ? "tel" : "name"}"
             />
             ${
               helperText
                 ? `<p class="helper-text" id="${id}-helper">${helperText}</p>`
                 : ""
             }
             <p class="field-error" id="${id}-error" hidden></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="form-panel" aria-labelledby="contact-form-title">
             <h2 id="contact-form-title">Contact support</h2>
             <p class="contact-note">
               Full name and email address are required. Phone number is optional.
             </p>
             <form class="contact-form" id="contact-form" novalidate>
               ${FormField({
                 id: "fullName",
                 label: "Full name",
                 type: "text",
                 placeholder: "Jordan Lee",
                 required: true
               })}
               ${FormField({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 placeholder: "jordan@example.com",
                 required: true
               })}
               ${FormField({
                 id: "phone",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "(555) 123-4567",
                 required: false,
                 helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
               })}
               <div class="submit-row">
                 <button class="submit-button" type="submit">Submit request</button>
                 <p class="status-message" id="form-status" hidden aria-live="polite"></p>
               </div>
             </form>
           </section>
         `;
       }

       function SupportPage() {
         return `
           <div class="support-layout">
             ${HeroPanel()}
             ${ContactForm()}
           </div>
         `;
       }

       app.innerHTML = PageShell(SupportPage());

       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");
       const fields = [
         {
           id: "fullName",
           validate(value) {
             return value.trim() ? "" : "Enter your full name.";
           }
         },
         {
           id: "email",
           validate(value) {
             if (!value.trim()) {
               return "Enter your email address.";
             }

             const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
             return emailPattern.test(value.trim()) ? "" : "Enter a valid email address.";
           }
         },
         {
           id: "phone",
           validate(value) {
             if (!value.trim()) {
               return "";
             }

             const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
             return phonePattern.test(value.trim())
               ? ""
               : "Use a valid phone number format, such as (555) 123-4567.";
           }
         }
       ];

       function setFieldState(fieldId, message) {
         const input = document.getElementById(fieldId);
         const field = input.closest(".form-field");
         const error = document.getElementById(fieldId + "-error");
         const isInvalid = Boolean(message);

         field.dataset.invalid = String(isInvalid);
         input.setAttribute("aria-invalid", String(isInvalid));
         error.textContent = message;
         error.hidden = !isInvalid;
       }

       function clearStatus() {
         status.hidden = true;
         status.textContent = "";
       }

       fields.forEach(({ id, validate }) => {
         const input = document.getElementById(id);
         input.addEventListener("input", () => {
           clearStatus();

           if (input.getAttribute("aria-invalid") === "true") {
             setFieldState(id, validate(input.value));
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         clearStatus();

         let firstInvalidField = null;
         let hasError = false;

         fields.forEach(({ id, validate }) => {
           const input = document.getElementById(id);
           const message = validate(input.value);
           setFieldState(id, message);

           if (message && !firstInvalidField) {
             firstInvalidField = input;
           }

           hasError = hasError || Boolean(message);
         });

         if (hasError) {
           firstInvalidField.focus();
           return;
         }

         status.textContent = "Thanks. Your support request is ready to be sent.";
         status.hidden = false;
         form.reset();
         fields.forEach(({ id }) => setFieldState(id, ""));
       });
     </script>
   </body>
